    assertTrue(isEqual(exchange.safeString2(inputDict, std::string("a"), std::string("f")), std::string("0.123")));
    assertTrue(isEqual(exchange.safeString2(inputDict, std::string("a"), std::string("str")), std::string("heLlo")));
    assertTrue(isEqual(exchange.safeString2(inputDict, std::string("a"), std::string("strNumber")), std::string("3")));
    assertTrue(isEqual(exchange.safeString2(inputList, 2, 0), std::string("Hi")));
    assertTrue(isEqual(exchange.safeString2(inputList, 2, std::string("emptyString")), std::any{}));
    // safeStringN
    assertTrue(isEqual(exchange.safeStringN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("i")}), std::string("1")));
    assertTrue(isEqual(exchange.safeStringN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("f")}), std::string("0.123")));
    assertTrue(isEqual(exchange.safeStringN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("str")}), std::string("heLlo")));
    assertTrue(isEqual(exchange.safeStringN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("strNumber")}), std::string("3")));
    assertTrue(isEqual(exchange.safeStringN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("emptyString")}), std::any{}));
    assertTrue(isEqual(exchange.safeStringN(inputList, ccxt::list{3, 2, 0}), std::string("Hi")));
    // With defaults
    assertTrue(isEqual(exchange.safeStringN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("nonexistent")}, std::string("MiXed_Case")), std::string("MiXed_Case")));
    // safeStringLower
    assertTrue(isEqual(exchange.safeStringLower(inputDict, std::string("i")), std::string("1")));
