void testSafeValue()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleex") },
    });
    std::any inputDict = helperDefaultInputDict();
    std::any inputList = ccxt::list{std::string("Hi"), 2};
    std::any compareDict = ccxt::dict {
        { std::string("a"), 1 },
    };
    std::any compareList = ccxt::list{1, 2, 3};
    // safeValue
    assertTrue(isEqual(exchange.safeValue(inputDict, std::string("i")), 1));
    assertTrue(isEqual(exchange.safeValue(inputDict, std::string("f")), 0.123));
    assertTrue(isEqual(exchange.safeValue(inputDict, std::string("bool")), true));
    assertTrue(equals(exchange.safeValue(inputDict, std::string("list")), compareList));
    std::any dictObject = exchange.safeValue(inputDict, std::string("dict"));
    assertTrue(equals(dictObject, compareDict));
    assertTrue(isEqual(exchange.safeValue(inputDict, std::string("str")), std::string("heLlo")));
    assertTrue(isEqual(exchange.safeValue(inputDict, std::string("strNumber")), std::string("3")));
    assertTrue(isEqual(exchange.safeValue(inputList, 0), std::string("Hi")));
    // safeValue2
    assertTrue(isEqual(exchange.safeValue2(inputDict, std::string("a"), std::string("i")), 1));
    assertTrue(isEqual(exchange.safeValue2(inputDict, std::string("a"), std::string("f")), 0.123));
    assertTrue(isEqual(exchange.safeValue2(inputDict, std::string("a"), std::string("bool")), true));
    assertTrue(equals(exchange.safeValue2(inputDict, std::string("a"), std::string("list")), compareList));
    dictObject = exchange.safeValue2(inputDict, std::string("a"), std::string("dict"));
    assertTrue(equals(dictObject, compareDict));
    assertTrue(isEqual(exchange.safeValue2(inputDict, std::string("a"), std::string("str")), std::string("heLlo")));
    assertTrue(isEqual(exchange.safeValue2(inputDict, std::string("a"), std::string("strNumber")), std::string("3")));
    assertTrue(isEqual(exchange.safeValue2(inputList, 2, 0), std::string("Hi")));
    // safeValueN
    assertTrue(isEqual(exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("i")}), 1));
    assertTrue(isEqual(exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("f")}), 0.123));
    assertTrue(isEqual(exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("bool")}), true));
    assertTrue(equals(exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("list")}), compareList));
    dictObject = exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("dict")});
    assertTrue(equals(dictObject, compareDict));
    assertTrue(isEqual(exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("str")}), std::string("heLlo")));
    assertTrue(isEqual(exchange.safeValueN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("strNumber")}), std::string("3")));
    assertTrue(isEqual(exchange.safeValueN(inputList, ccxt::list{3, 2, 0}), std::string("Hi")));
}
void testSafeDict()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleex") },
    });
    std::any inputDict = helperDefaultInputDict();
    std::any inputList = ccxt::list{std::string("Hi"), 2};
    std::any compareDict = ccxt::dict {
        { std::string("a"), 1 },
    };
    // safeDict
    std::any dictObject = exchange.safeDict(inputDict, std::string("dict"));
    assertTrue(equals(dictObject, compareDict));
    std::any listObject = exchange.safeDict(inputDict, std::string("list"));
    assertTrue(isEqual(listObject, std::any{}));
    assertTrue(isEqual(exchange.safeDict(inputList, 1), std::any{}));
    // safeDict2
    dictObject = exchange.safeDict2(inputDict, std::string("a"), std::string("dict"));
    assertTrue(equals(dictObject, compareDict));
    listObject = exchange.safeDict2(inputDict, std::string("a"), std::string("list"));
    assertTrue(isEqual(listObject, std::any{}));
    // @ts-expect-error
    assertTrue(isEqual(exchange.safeDict2(inputList, 2, 1), std::any{}));
    // safeDictN
    dictObject = exchange.safeDictN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("dict")});
    assertTrue(equals(dictObject, compareDict));
    listObject = exchange.safeDictN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("list")});
    assertTrue(isEqual(listObject, std::any{}));
    assertTrue(isEqual(exchange.safeDictN(inputList, ccxt::list{3, 2, 1}), std::any{}));
}
void testSafeList()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleex") },
    });
    std::any inputDict = helperDefaultInputDict();
    std::any inputList = ccxt::list{std::string("Hi"), 2};
    // safeList
    assertTrue(isEqual(exchange.safeList(inputDict, std::string("dict")), std::any{}));
    assertTrue(isEqual(exchange.safeList(inputList, 1), std::any{}));
    std::any arrayOfDicts = exchange.safeList(inputDict, std::string("listOfDicts"));
    assertTrue(equals(::getValue(arrayOfDicts, 0), ccxt::dict {
        { std::string("a"), 1 },
    }));
    // safeList2
    assertTrue(isEqual(exchange.safeList2(inputDict, std::string("a"), std::string("dict")), std::any{}));
    // @ts-expect-error
    assertTrue(isEqual(exchange.safeList2(inputList, 2, 1), std::any{}));
    // safeListN
    assertTrue(isEqual(exchange.safeListN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("dict")}), std::any{}));
    assertTrue(isEqual(exchange.safeListN(inputList, ccxt::list{3, 2, 1}), std::any{}));
}
void testSafeInteger()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleex") },
    });
    // safeInteger
    std::any inputDict = helperDefaultInputDict();
    std::any inputList = ccxt::list{std::string("Hi"), 2};
    std::any factor = 10;
    assertTrue(isEqual(exchange.safeInteger(inputDict, std::string("i")), 1));
    assertTrue(isEqual(exchange.safeInteger(inputDict, std::string("f")), 0));
    assertTrue(isEqual(exchange.safeInteger(inputDict, std::string("strNumber")), 3));
    assertTrue(isEqual(exchange.safeInteger(inputList, 1), 2));
    // safeInteger2
    assertTrue(isEqual(exchange.safeInteger2(inputDict, std::string("a"), std::string("i")), 1));
    assertTrue(isEqual(exchange.safeInteger2(inputDict, std::string("a"), std::string("f")), 0));
    assertTrue(isEqual(exchange.safeInteger2(inputDict, std::string("a"), std::string("strNumber")), 3));
    assertTrue(isEqual(exchange.safeInteger2(inputList, 2, 1), 2));
    // safeIntegerN
    assertTrue(isEqual(exchange.safeIntegerN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("i")}), 1));
    assertTrue(isEqual(exchange.safeIntegerN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("f")}), 0));
    assertTrue(isEqual(exchange.safeIntegerN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("strNumber")}), 3));
    assertTrue(isEqual(exchange.safeIntegerN(inputList, ccxt::list{3, 2, 1}), 2));
    // safeIntegerOmitZero
    assertTrue(isEqual(exchange.safeIntegerOmitZero(inputDict, std::string("i")), 1));
    assertTrue(isEqual(exchange.safeIntegerOmitZero(inputDict, std::string("f")), std::any{}));
    assertTrue(isEqual(exchange.safeIntegerOmitZero(inputDict, std::string("strNumber")), 3));
    assertTrue(isEqual(exchange.safeIntegerOmitZero(inputList, 1), 2));
    // safeIntegerProduct
    assertTrue(isEqual(exchange.safeIntegerProduct(inputDict, std::string("i"), factor), 10));
    assertTrue(isEqual(exchange.safeIntegerProduct(inputDict, std::string("f"), factor), 1)); // NB the result is 1
    assertTrue(isEqual(exchange.safeIntegerProduct(inputDict, std::string("strNumber"), factor), 30));
    assertTrue(isEqual(exchange.safeIntegerProduct(inputList, 1, factor), 20));
    assertTrue(isEqual(exchange.safeIntegerProduct(inputDict, std::string("longInt"), 0.000001), 123456789));
    assertTrue(isEqual(exchange.safeIntegerProduct(inputDict, std::string("inexistent"), 0.000001, 123456789), 123456789));
    // safeIntegerProduct2
    assertTrue(isEqual(exchange.safeIntegerProduct2(inputDict, std::string("a"), std::string("i"), factor), 10));
    assertTrue(isEqual(exchange.safeIntegerProduct2(inputDict, std::string("a"), std::string("f"), factor), 1)); // NB the result is 1
    assertTrue(isEqual(exchange.safeIntegerProduct2(inputDict, std::string("a"), std::string("strNumber"), factor), 30));
    assertTrue(isEqual(exchange.safeIntegerProduct2(inputList, 2, 1, factor), 20));
    // safeIntegerProductN
    assertTrue(isEqual(exchange.safeIntegerProductN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("i")}, factor), 10));
    assertTrue(isEqual(exchange.safeIntegerProductN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("f")}, factor), 1)); // NB the result is 1
    assertTrue(isEqual(exchange.safeIntegerProductN(inputDict, ccxt::list{std::string("a"), std::string("b"), std::string("strNumber")}, factor), 30));
    assertTrue(isEqual(exchange.safeIntegerProductN(inputList, ccxt::list{3, 2, 1}, factor), 20));
}
